<script setup lang="ts">
import {Head,useForm,router} from '@inertiajs/vue3';
import {Check,X,UserRoundX} from 'lucide-vue-next';
import AdminLayout from '../../../../../CORE/Resources/js/Layouts/AdminLayout.vue';
import PageHeader from '../../../../../CORE/Resources/js/Components/PageHeader.vue';
import {Button} from '@/components/ui/button'; import {Input} from '@/components/ui/input'; import {Label} from '@/components/ui/label';
import DataTable,{type DataTableColumn} from '../../../../../CORE/Resources/js/Components/DataTable.vue';
import type {Paginator} from '../../../../../CORE/Resources/js/types';
interface Row{id:number;employee_id:string;employee:string;last_working_date:string;reason:string;status:string;decision_note?:string}
defineProps<{requests:Paginator<Row>}>();
const form=useForm({employee_id:'',last_working_date:'',reason:''});
function submit(){form.post(route('hrm.resignations.store'),{preserveScroll:true,onSuccess(){form.reset()}})}
function decide(row:Row,decision:'Approved'|'Rejected'){const note=prompt('Optional decision note')||'';router.post(route('hrm.resignations.decision',row.id),{decision,decision_note:note},{preserveScroll:true})}
const columns:DataTableColumn[]=[{key:'employee_id',label:'Employee'},{key:'last_working_date',label:'Last working day'},{key:'reason',label:'Reason'},{key:'status',label:'Status'},{key:'decision_note',label:'Decision note'},{key:'actions',label:'',align:'right',exportable:false}];
</script>
<template><AdminLayout :breadcrumbs="[{title:'HRM'},{title:'Resignations'}]"><Head title="Employee resignations"/><div class="mb-5 flex items-center gap-3"><UserRoundX class="size-6"/><div><p class="text-sm text-muted-foreground">Submit, review and approve last-working-day requests. Approved records are additive and exclude the employee from payroll periods after their last working day.</p></div></div><form @submit.prevent="submit" class="mb-6 grid gap-4 rounded-xl border bg-card p-4 md:grid-cols-4"><div><Label>Employee ID</Label><Input v-model="form.employee_id" placeholder="Exact employee_id"/><p v-if="form.errors.employee_id" class="text-xs text-destructive">{{form.errors.employee_id}}</p></div><div><Label>Last working day</Label><Input v-model="form.last_working_date" type="date"/><p v-if="form.errors.last_working_date" class="text-xs text-destructive">{{form.errors.last_working_date}}</p></div><div class="md:col-span-2"><Label>Reason</Label><Input v-model="form.reason" placeholder="Reason for resignation"/><p v-if="form.errors.reason" class="text-xs text-destructive">{{form.errors.reason}}</p></div><div class="md:col-span-4"><Button :disabled="form.processing">Submit resignation request</Button></div></form>    <PageHeader title="Employee resignation flow" description="Submit, review and approve last-working-day requests. Approved records are additive and exclude the employee from payroll periods after their last working day." :icon="Check" >
    <DataTable route-name="hrm.resignations.index" title="Resignation requests" :columns="columns" :rows="requests.data as unknown as Record<string,unknown>[]" :meta="requests.meta" :filter-defs="[{key:'status',label:'Status',kind:'select',options:[{value:'Pending',label:'Pending'},{value:'Approved',label:'Approved'},{value:'Rejected',label:'Rejected'}]}]"><template #cell-employee_id="{row}"><div><strong>{{row.employee}}</strong><span class="block font-mono text-xs text-muted-foreground">{{row.employee_id}}</span></div></template><template #cell-reason="{row}"><span class="line-clamp-2">{{row.reason}}</span></template><template #cell-status="{row}"><span class="rounded-full border px-2 py-1 text-xs" :class="row.status==='Pending'?'bg-amber-50 text-amber-700':row.status==='Approved'?'bg-emerald-50 text-emerald-700':'bg-red-50 text-red-700'">{{row.status}}</span></template><template #cell-actions="{row}"><div v-if="row.status==='Pending'" class="flex justify-end gap-2"><Button size="sm" class="bg-emerald-600" @click="decide(row as unknown as Row,'Approved')"><Check class="size-4"/>Approve</Button><Button size="icon" variant="destructive" @click="decide(row as unknown as Row,'Rejected')"><X class="size-4"/></Button></div></template></DataTable>    </PageHeader>
  </AdminLayout></template>